    public static void main(String[] args) {
        Todo t = new Todo(1, "Belajar Lombok");
        System.out.println(t.getId() + " " + t.getJudul() + " " + t.isSelesai());
    }
}

@Getter
class Todo {
    private int id;
    private String judul;
    private boolean selesai;

    Todo(int id, String judul) {
        this.id = id;
        this.judul = judul;
    }
}

