import java.util.*;

import lombok.*;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        List<Menu> daftar = new ArrayList<>();
        while (in.hasNextLine()) {
            String[] d = in.nextLine().split(";");
            Menu m = new Menu();
            m.setNama(d[0]);
            m.setHarga(Integer.parseInt(d[1]));
            daftar.add(m);
        }
        for (Menu m : daftar) {
            m.setHarga(m.getHarga() - m.getHarga() / 10);
            System.out.println(m.getNama() + ": " + m.getHarga());
        }
    }
}

class Menu {
    private String nama;
    private int harga;
}

